SET search_path = pg_catalog, public;

CREATE TABLE "public"."exits" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."exits_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "full_name" text,
  "designation" text,
  "current_project" text,
  "join_date" text,
  "exit_reason" text,
  "exit_date" text,
  "issue_date" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "employee_id" text,
  "employee_sys_id" bigint,
  "deleted_at" timestamp with time zone,
  "deleted_by" uuid,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "status" text DEFAULT 'Draft'::text NOT NULL,
  "exit_type" text,
  "effective_exit_date" date,
  "related_transfer_id" bigint,
  "completed_at" timestamp with time zone,
  "completed_by" uuid,
  "cancelled_at" timestamp with time zone,
  "cancelled_by" uuid,
  "cancellation_reason" text,
  "completion_remarks" text
) USING "heap";
ALTER TABLE "public"."exits" OWNER TO "postgres";
